# CI — unit tests, build and Playwright e2e on Chromium, Firefox and WebKit (DEC-13, ADR-005).
# Runs on GitHub-hosted runners because the dev container cannot download Playwright browsers.
# No secrets, no paid services, no deploy.
name: CI

on:
  push:
    branches: ['**']
  pull_request:
  workflow_dispatch:

permissions:
  contents: read

concurrency:
  group: ci-${{ github.ref }}
  cancel-in-progress: true

jobs:
  test:
    name: Unit, build and e2e (3 engines)
    runs-on: ubuntu-latest
    timeout-minutes: 15
    defaults:
      run:
        working-directory: sabee-khan-calculator
    env:
      CI: 'true'
    steps:
      - name: Check out
        uses: actions/checkout@v4

      - name: Set up Node from .nvmrc
        uses: actions/setup-node@v4
        with:
          node-version-file: sabee-khan-calculator/.nvmrc
          cache: npm
          cache-dependency-path: sabee-khan-calculator/package-lock.json

      - name: Node version
        run: |
          node --version && npm --version
          echo "::notice title=Node::$(node --version)"

      - name: Install dependencies
        run: npm ci

      - name: Audit dependencies (high and critical fail the build)
        run: npm audit --audit-level=high

      - name: Unit tests
        run: npm test -- --reporter=default --reporter=json --outputFile=test-results/unit-results.json

      - name: Publish unit summary
        if: ${{ always() }}
        run: node scripts/ci-summary.mjs --unit

      - name: Build
        run: npm run build

      - name: Install Playwright browsers
        run: npx playwright install --with-deps chromium firefox webkit

      - name: E2E tests (Chromium, Firefox, WebKit)
        run: npx playwright test

      - name: Publish e2e summary
        if: ${{ always() }}
        run: node scripts/ci-summary.mjs

      - name: Upload Playwright report and test results
        if: ${{ always() }}
        uses: actions/upload-artifact@v4
        with:
          name: playwright-report
          path: |
            sabee-khan-calculator/playwright-report/
            sabee-khan-calculator/test-results/
          retention-days: 14
          if-no-files-found: ignore
/// <reference types="vitest/config" />
import { defineConfig, type Plugin } from 'vite';
import { MESSAGES, type MessageId } from './src/messages';

/** Replaces %M-n% placeholders in index.html with catalogue text, so messages.ts stays the single source. */
function catalogueHtml(): Plugin {
  return {
    name: 'catalogue-html',
    transformIndexHtml(html) {
      return html.replace(/%(M-\d+)%/g, (placeholder, id: string) => {
        if (!(id in MESSAGES)) throw new Error(`index.html: unknown message ${placeholder}`);
        return escapeHtml(MESSAGES[id as MessageId]);
      });
    },
  };
}

function escapeHtml(text: string): string {
  return text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

// ADR-008: relative base so the same build works from `vite preview` and any GitHub Pages sub-path.
export default defineConfig({
  base: './',
  plugins: [catalogueHtml()],
  build: {
    outDir: 'dist',
    emptyOutDir: true,
  },
  preview: {
    host: '127.0.0.1',
    port: 4173,
    strictPort: true,
  },
  // ADR-005: Vitest runs pure modules only, in the node environment.
  test: {
    environment: 'node',
    include: ['tests/unit/**/*.test.ts'],
  },
});
