import { defineConfig, devices } from '@playwright/test';

const PORT = 4173;
const BASE_URL = `http://127.0.0.1:${PORT}/`;
const isCI = Boolean(process.env['CI']);

// ADR-005: e2e runs against the production build served by `vite preview`.
export default defineConfig({
  testDir: './tests/e2e',
  fullyParallel: true,
  forbidOnly: isCI,
  retries: 0, // never mask failures with retries, locally or in CI
  // CI also writes a JSON report; scripts/ci-summary.mjs turns it into per-engine check annotations.
  reporter: isCI
    ? [['list'], ['html', { open: 'never' }], ['json', { outputFile: 'test-results/e2e-results.json' }]]
    : 'list',
  use: {
    baseURL: BASE_URL,
    trace: 'retain-on-failure',
  },
  projects: [
    { name: 'chromium', use: { ...devices['Desktop Chrome'] } },
    { name: 'firefox', use: { ...devices['Desktop Firefox'] } },
    { name: 'webkit', use: { ...devices['Desktop Safari'] } },
  ],
  webServer: {
    command: `npm run build && npm run preview -- --host 127.0.0.1 --port ${PORT} --strictPort`,
    url: BASE_URL,
    reuseExistingServer: !isCI,
    timeout: 120_000,
  },
});
import { test, expect } from './fixtures';
import { MESSAGES } from '../../src/messages';

// Sprint 0 smoke tests (test-plan.md E-0.1..E-0.4). Expected text comes from messages.ts.

test.beforeEach(async ({ page }) => {
  await page.goto('./');
});

test('E-0.1 page loads with the title M-30 and one h1 (M-32)', async ({ page }) => {
  await expect(page).toHaveTitle(MESSAGES['M-30']);
  await expect(page.locator('html')).toHaveAttribute('lang', 'en');
  await expect(page.getByRole('heading', { level: 1 })).toHaveText(MESSAGES['M-32']);
  await expect(page.getByRole('heading')).toHaveCount(1);
});

test('E-0.2 three labelled inputs (M-34..M-36), empty earned and total, pass mark "70"', async ({ page }) => {
  const earned = page.getByLabel(MESSAGES['M-34'], { exact: true });
  const total = page.getByLabel(MESSAGES['M-35'], { exact: true });
  const pass = page.getByLabel(MESSAGES['M-36'] + MESSAGES['M-37'], { exact: true });

  for (const input of [earned, total, pass]) {
    await expect(input).toBeVisible();
    await expect(input).toHaveAttribute('type', 'text');
    await expect(input).toHaveAttribute('inputmode', 'decimal');
    await expect(input).toHaveAttribute('autocomplete', 'off');
    await expect(input).not.toHaveAttribute('aria-invalid', 'true');
    const describedBy = await input.getAttribute('aria-describedby');
    expect(describedBy).toBeTruthy();
    await expect(page.locator(`#${describedBy}`)).toBeAttached();
    await expect(page.locator(`#${describedBy}`)).toHaveText('');
  }
  await expect(earned).toHaveValue('');
  await expect(total).toHaveValue('');
  await expect(pass).toHaveValue('70');

  // Tab order follows the DOM: earned → total → pass mark → Next learner.
  await earned.focus();
  await page.keyboard.press('Tab');
  await expect(total).toBeFocused();
  await page.keyboard.press('Tab');
  await expect(pass).toBeFocused();
  await page.keyboard.press('Tab');
  await expect(page.getByRole('button', { name: MESSAGES['M-25'] })).toBeFocused();
});

test('E-0.3 idle state: M-1 in the result area, "Next learner" button and Esc hint', async ({ page }) => {
  const result = page.getByRole('region', { name: MESSAGES['M-39'] });
  await expect(result).toBeVisible();
  await expect(result).toContainText(MESSAGES['M-1']);
  await expect(page.getByRole('status')).toBeAttached();

  const button = page.getByRole('button', { name: MESSAGES['M-25'] });
  await expect(button).toBeVisible();
  await expect(button).toHaveAttribute('type', 'button');
  await expect(button).toHaveAttribute('aria-keyshortcuts', 'Escape');
  await expect(page.getByText(MESSAGES['M-40'])).toBeVisible();

  const body = (await page.locator('body').innerText()).toLowerCase();
  for (const bad of ['nan', 'undefined', 'infinity', 'null']) {
    expect(body).not.toContain(bad);
  }

  for (const target of [button, page.getByLabel(MESSAGES['M-34'], { exact: true })]) {
    const box = await target.boundingBox();
    expect(box?.height ?? 0).toBeGreaterThanOrEqual(44);
    expect(box?.width ?? 0).toBeGreaterThanOrEqual(44);
  }
});

test('E-0.4 no horizontal scroll at 320 px', async ({ page }) => {
  await page.setViewportSize({ width: 320, height: 800 });
  await expect(page.getByText(MESSAGES['M-1'])).toBeVisible();
  const widths = await page.evaluate(() => ({
    scroll: document.documentElement.scrollWidth,
    client: document.documentElement.clientWidth,
  }));
  expect(widths.scroll).toBeLessThanOrEqual(widths.client);
});
import { test as base, expect } from '@playwright/test';

// DoD: any console error, console warning or uncaught page error fails the test.
export const test = base.extend<{ consoleGuard: void }>({
  consoleGuard: [
    async ({ page }, use) => {
      const problems: string[] = [];
      page.on('console', (msg) => {
        if (msg.type() === 'error' || msg.type() === 'warning') {
          problems.push(`console.${msg.type()}: ${msg.text()}`);
        }
      });
      page.on('pageerror', (err) => problems.push(`pageerror: ${err.message}`));
      await use();
      expect(problems, 'console errors, warnings or page errors').toEqual([]);
    },
    { auto: true },
  ],
});

export { expect };
