import { chromium } from '/home/user/Web-Calculator-fresh/sabee-khan-calculator/node_modules/@playwright/test/index.mjs';
const out = process.argv[2];
const b = await chromium.launch();
const errs = [];
const states = { idle: null, pass: ['17.5','23','70'], error: ['abc','-5','70'], gap: ['16','23.33','70'], neg: ['-5','23','70'] };
for (const scheme of ['light','dark']) for (const w of [375,1280]) for (const [name, v] of Object.entries(states)) {
  if ((name==='gap'||name==='neg') && (w!==375||scheme!=='light')) continue;
  const p = await b.newPage({ viewport: { width: w, height: 900 }, colorScheme: scheme });
  p.on('console', m => { if (['error','warning'].includes(m.type())) errs.push(m.text()); });
  p.on('pageerror', e => errs.push(e.message));
  await p.goto('http://127.0.0.1:4173/');
  if (v) { const ins = p.locator('input'); for (let i=0;i<3;i++) await ins.nth(i).fill(v[i]); }
  await p.waitForTimeout(200);
  const card = await p.locator('.card').boundingBox();
  const rb = await p.locator('.result-body').boundingBox();
  console.log(scheme, w, name, 'card bottom', Math.round(card.y+card.height), 'resultBody bottom', Math.round(rb.y+rb.height));
  await p.screenshot({ path: `${out}/s2p-${name}-${w}-${scheme}.png`, fullPage: true });
  await p.close();
}
const p = await b.newPage(); await p.goto('http://127.0.0.1:4173/favicon.svg'); console.log('favicon', (await p.content()).includes('<svg') || (await p.locator('svg').count()));
console.log('console errors:', errs.length ? errs : 'none');
await b.close();
EOF
sleep 2; node $S/shots.mjs $S

